"""CODE quyết cơ cấu (layout, loại slot, tín hiệu nào) — LLM chỉ lấp nội dung trong khung.
Xác định (deterministic): cùng đầu vào → cùng kế hoạch."""
from __future__ import annotations
import re
from datetime import date, timedelta

_SKIP = {"the", "and", "2026", "2025", "surf", "trough", "blitz", "wash", "gig", "pick", "early", "figure", "eight"}


def _topic_tokens(label: str) -> set:
    return {t for t in re.split(r"[^a-z0-9]+", str(label).lower()) if len(t) > 3 and t not in _SKIP}


def _clashes(sig, taken: list) -> bool:
    """Hai tín hiệu nói về cùng một con vật/chủ đề (GAP:goose vs LEDGER:EARLY-GOOSE-CUT-CORN)
    thì không nên chiếm hai slot khác nhau trong cùng một lượt — người duyệt sẽ thấy trùng."""
    mine = _topic_tokens(sig.label)
    return bool(mine) and any(mine & t for t in taken)


def _moment(sig) -> dict:
    x = sig.extra or {}
    return {"key": sig.ref.split(":", 1)[-1], "label": sig.label, "date": x.get("date"),
            "idea_by": x.get("idea_by"), "order_by": x.get("order_by"),
            "moments": list(x.get("moments") or []), "buyer": x.get("buyer"), "avoid": list(x.get("avoid") or [])}


def _phu_mua(brand, signals, slots: list) -> None:
    """2.38.0 PHỦ MÙA. Đo 02/10: 4/4 thẻ Gerbera là PROVEN_EXTENSION, 3/4 'evergreen' — lịch chỉ tới slot
    CALENDAR_PLAY nên mẫu thắng không bao giờ được kéo VÀO dịp sắp tới. Cartridge khai `season_overlay`
    (0..1) thì đúng tỉ lệ đó số slot mang một DỊP đang mở (hạn gần nhất trước), kèm khoảnh khắc thật.
    Không khai, hoặc lịch không có `moments` → không làm gì: brand khác giữ nguyên prompt từng byte."""
    ov = float(brand.raw.get("season_overlay", 0) or 0)
    cal = [s for s in signals.items if s.kind == "calendar" and (s.extra or {}).get("moments")]
    if ov <= 0 or not cal or not slots:
        return
    cal.sort(key=lambda s: s.days_left if s.days_left is not None else 999)
    for sl in slots:
        sg = sl.get("signal")
        if sg is not None and sg.kind == "calendar" and (sg.extra or {}).get("moments"):
            sl["moment"] = _moment(sg)
    want = min(len(slots), int(round(ov * len(slots))))
    have, k = sum(1 for sl in slots if sl.get("moment")), 0
    for sl in slots:
        if have >= want:
            break
        if sl.get("moment"):
            continue
        sl["moment"] = _moment(cal[k % len(cal)])
        k += 1
        have += 1


def _layout_sequence(mix: dict, n: int) -> list:
    counts = {k: int(round(v * n)) for k, v in mix.items()}
    while sum(counts.values()) != n:                      # sửa làm tròn
        k = max(mix, key=mix.get) if sum(counts.values()) < n else max(counts, key=counts.get)
        counts[k] += 1 if sum(counts.values()) < n else -1
    seq, keys = [], sorted(counts, key=lambda k: -counts[k])
    while len(seq) < n:
        for k in keys:
            if counts[k] > 0:
                seq.append(k)
                counts[k] -= 1
    return seq


def _fb_key(sig) -> str:
    """Khoá chủ thể của một tín hiệu để tra điểm phản hồi: từ nhãn, bỏ hậu tố ngày/id."""
    lab = str(sig.label).lower()
    lab = re.sub(r"-?\d{4}$", "", lab).strip("-_ ")
    return lab.replace("-", "_").replace(" ", "_")


def plan(brand, signals, history: list, today: date, n: int | None = None, feedback: dict | None = None) -> list:
    from . import feedback as fbmod
    n = n or brand.per_run
    lru_days = brand.raw.get("signal_lru_days", 14)
    cutoff = (today - timedelta(days=lru_days)).isoformat()
    recent = {h.get("signal_ref") for h in history if h.get("date", "") >= cutoff}
    pool = {}
    for s in signals.items:
        pool.setdefault(s.kind, []).append(s)
    for kind in pool:                                   # điểm cao lên trước (ổn định): hook units thật > CSV cũ
        pool[kind].sort(key=lambda s: -(s.score or 0))
    if feedback:
        # Ổn định (stable sort): điểm bằng nhau giữ thứ tự gốc theo score/kill_date.
        for kind in pool:
            pool[kind].sort(key=lambda s: -fbmod.score_for_label(feedback, s.label))
    used, times, topics = set(), {}, []
    # Cơ cấu slot co giãn theo n: chạy --n 6 phải giữ ĐÚNG TỈ LỆ các loại slot,
    # không được cắt cụt danh sách và làm mất hẳn loại đứng sau (lỗi đã bắt được bằng test lịch).
    total = sum(int(st["count"]) for st in brand.slot_types) or 1
    share = {st["key"]: int(st["count"]) * n / total for st in brand.slot_types}
    counts = {k: int(v) for k, v in share.items()}
    order = sorted(share, key=lambda k: -(share[k] - counts[k]))
    i = 0
    while sum(counts.values()) < n:                        # chia phần dư cho phần lẻ lớn nhất
        counts[order[i % len(order)]] += 1
        i += 1
    while sum(counts.values()) > n:
        big = max(counts, key=counts.get)
        counts[big] -= 1
    types = []
    for st in brand.slot_types:
        types += [st] * counts[st["key"]]
    layouts = _layout_sequence(brand.layout_mix, n)
    slots = []
    max_per_signal = int(brand.raw.get("max_ideas_per_signal", 1))
    # Lăng kính kể chuyện xoay vòng: đúng như layout, CODE quyết để không thể 10 ý cùng một giọng.
    # Hôm nay bắt đầu ở vị trí khác hôm qua (theo ngày) để lăng kính đầu tiên không bao giờ cố định.
    # Đo 30/09 trên 100 thẻ Gerbera: 9 lens xoay đều → 6 lens "golfer tự giễu" chiếm 2/3, lens quan hệ
    # (SPOUSE_TRUCE, THE_GROUP_CHAT, DAD_ENERGY) chỉ 19%. Cartridge khai `lens_weights: {KEY: n}` thì
    # lens nặng hơn xuất hiện nhiều hơn; không khai thì đều như cũ.
    lw = brand.raw.get("lens_weights") or {}
    lenses = [l["key"] for l in (brand.story_lenses or []) for _ in range(max(1, int(lw.get(l["key"], 1))))]
    lens_offset = today.toordinal() % len(lenses) if lenses else 0
    # VAI NGƯỜI MUA / NGƯỜI NHẬN — xoay vòng như lens. Đo 30/09: 98/100 thẻ Gerbera "golfer himself",
    # 2 thẻ "wife gifting" — trong khi chính cartridge ghi VỢ quyết định rất nhiều đơn. LLM mặc định
    # người mua = người mặc vì không ai giao vai. Cartridge khai `gift_roles: [{who, to, weight}]`.
    roles = [r for r in (brand.raw.get("gift_roles") or []) for _ in range(max(1, int(r.get("weight", 1))))]
    role_offset = (today.toordinal() * 3) % len(roles) if roles else 0
    for i, (st, lay) in enumerate(zip(types, layouts), start=1):
        pick, clash = None, False
        # Lượt 1: tín hiệu chưa dùng hôm nay và chưa dùng trong LRU.
        for kind in st["draws"]:
            for s in pool.get(kind, []):
                if s.ref not in used and s.ref not in recent and not _clashes(s, topics):
                    pick = s
                    break
            if pick:
                break
        # Lượt 2: cho phép dùng lại tín hiệu, tối đa max_ideas_per_signal lần.
        # Chữ ký vẫn phải khác nhau (loài × tư thế × kiểu slot) nên đây là biến thể thật,
        # không phải đổi tên. Không có lượt 2 thì không thể ra 15-20 ý/ngày.
        if pick is None and max_per_signal > 1:
            cands = [s for kind in st["draws"] for s in pool.get(kind, [])
                     if times.get(s.ref, 0) < max_per_signal]
            fresh = [s for s in cands if not _clashes(s, topics)]
            clash = not fresh and bool(cands)          # hết hẳn mới chấp nhận trùng chủ đề — và PHẢI báo
            cands = fresh or cands
            if cands:
                pick = min(cands, key=lambda s: (times.get(s.ref, 0), -(s.score or 0)))
        if pick:
            used.add(pick.ref)
            times[pick.ref] = times.get(pick.ref, 0) + 1
            tt = _topic_tokens(pick.label)
            if tt:
                topics.append(tt)
        slots.append({"slot": i, "layout": lay, "slot_type": st["key"], "signal": pick,
                      "variant": times.get(pick.ref, 1) if pick else 1, "topic_clash": clash,
                      "lens": lenses[(lens_offset + i - 1) % len(lenses)] if lenses else None,
                      "gift_role": roles[(role_offset + i - 1) % len(roles)] if roles else None})
    _phu_mua(brand, signals, slots)
    # SERIES: gom một khối slot thành một bộ (swap 1 trục, giữ khung). Etsy learnings: cơ chế ROI cao nhất —
    # người mua mua 2-4 cái, người duyệt duyệt 1 khung 4 lần. Cartridge khai `series:` {every_n_days, size, axes}.
    ser = brand.raw.get("series") or {}
    size = int(ser.get("size", 0) or 0)
    if size >= 2 and len(slots) >= size and ser.get("axes"):
        every = int(ser.get("every_n_days", 1) or 1)
        if today.toordinal() % every == 0:
            axes = ser["axes"]
            axis = axes[(today.toordinal() // every) % len(axes)]
            first = len(slots) - size                       # khối cuối: ưu tiên slot có tín hiệu thật cho phần đầu
            sid = f"S{today.strftime('%Y%m%d')}"
            for k, sl in enumerate(slots[first:first + size], start=1):
                sl["series"] = {"id": sid, "axis": axis["key"], "role": k, "size": size,
                                "what": axis.get("what", ""), "rule": axis.get("rule", "")}
                sl["layout"] = axis.get("layout", sl["layout"])
                sl["lens"] = axis.get("lens", sl["lens"])   # cả bộ chung một lens — khung chung, chỉ đổi trục
    return slots
